using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough into a circle\n3. Spread crushed tomatoes evenly\n4. Add torn mozzarella pieces\n5. Bake for 10-12 minutes\n6. Top with fresh basil and drizzle olive oil", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast, Yogurt, Tikka masala paste, Onion, Garlic, Ginger, Canned tomatoes, Heavy cream, Rice", Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or pan-fry chicken until charred\n3. Sauté onion, garlic, and ginger\n4. Add tikka paste and tomatoes, simmer 15 min\n5. Stir in cream and cooked chicken\n6. Serve over basmati rice", AverageRating = 4.8, RatingCount = 24 },
            new() { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheddar cheese, Sour cream, Salsa", Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water, simmer 5 min\n3. Warm tortillas in a dry pan\n4. Assemble tacos with beef and toppings\n5. Serve with salsa and sour cream", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Shrimp, Egg, Bean sprouts, Green onion, Peanuts, Lime, Fish sauce, Tamarind paste, Sugar", Steps = "1. Soak rice noodles in warm water 30 min\n2. Stir-fry shrimp until pink, set aside\n3. Scramble egg in the wok\n4. Add drained noodles and sauce mixture\n5. Toss with shrimp and bean sprouts\n6. Garnish with peanuts, green onion, and lime", AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 5, Title = "Caesar Salad", Category = "American", Ingredients = "Romaine lettuce, Parmesan cheese, Croutons, Caesar dressing, Lemon, Anchovy paste, Garlic", Steps = "1. Wash and chop romaine lettuce\n2. Make dressing: whisk anchovy paste, garlic, lemon juice, and parmesan\n3. Toss lettuce with dressing\n4. Top with croutons and shaved parmesan\n5. Serve immediately", AverageRating = 3.9, RatingCount = 6 },
            new() { Id = 6, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Egg yolks, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water until al dente\n2. Crisp guanciale in a pan\n3. Whisk egg yolks with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture quickly\n6. Serve with extra pecorino and pepper", AverageRating = 4.7, RatingCount = 19 },
            new() { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Coconut milk, Green curry paste, Chicken thigh, Thai basil, Bamboo shoots, Bell pepper, Fish sauce, Sugar, Jasmine rice", Steps = "1. Heat coconut cream in a pot until oil separates\n2. Fry green curry paste for 2 minutes\n3. Add chicken, cook until white\n4. Pour in coconut milk, add bamboo shoots and peppers\n5. Season with fish sauce and sugar\n6. Stir in Thai basil, serve over jasmine rice", AverageRating = 4.4, RatingCount = 11 },
            new() { Id = 8, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt, Garlic", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño, and cilantro\n4. Mix everything together\n5. Season with lime juice, salt, and garlic\n6. Serve with tortilla chips", AverageRating = 4.3, RatingCount = 9 },
        };
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
        recipe.RatingCount = allRatings.Count + recipe.RatingCount;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

